INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 10046, 0.0, 102301, 0.0, 2, 24, 24001, "2020/07/31 12:00:00", 401, 0.0, "アヤネ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 10046, 0.0, 102301, 2.21, 2, 24, 24002, "2020/07/31 12:00:00", 402, 0.0, "アヤネ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 10046, 0.0, 102301, 0.0, 2, 24, 24003, "2020/07/31 12:00:00", 403, 0.0, "アヤネ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 10046, 0.0, 192201, 1.99, 1, 24, 24004, "2020/07/31 12:00:00", 701, 0.0, "アサヒ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 10046, 0.0, 192201, 2.21, 2, 24, 24005, "2020/07/31 12:00:00", 702, 0.0, "アサヒ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 10046, 0.0, 192201, 3.33, 1, 24, 24006, "2020/07/31 12:00:00", 703, 0.0, "アサヒ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 10046, 0.0, 192301, 0.0, 2, 24, 24007, "2020/07/31 12:00:00", 801, 0.0, "部員３");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 10046, 0.0, 192301, 2.68, 2, 24, 24008, "2020/07/31 12:00:00", 802, 0.0, "部員３");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 10046, 0.0, 192301, 0.0, 2, 24, 24009, "2020/07/31 12:00:00", 803, 0.0, "部員３");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "やった！", 10046, 0.0, 192501, 0.0, 1, 24, 24010, "2020/07/31 12:00:00", 501, 0.0, "");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "勝ったよ！", 10046, 0.0, 192501, 0.0, 1, 24, 24011, "2020/07/31 12:00:00", 502, 0.0, "");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "いい調子！", 10046, 0.0, 192501, 0.0, 1, 24, 24012, "2020/07/31 12:00:00", 503, 0.0, "");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 6, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 10046, 0.0, 113501, 5.33, 2, 24, 24013, "2020/07/31 12:00:00", 111, 0.0, "ミサト");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 10046, 0.0, 113501, 6.85, 2, 24, 24014, "2020/07/31 12:00:00", 112, 0.0, "ミサト");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 10046, 0.0, 113501, 3.0, 2, 24, 24015, "2020/07/31 12:00:00", 113, 0.0, "ミサト");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 10046, 0.0, 192401, 6.11, 2, 24, 24016, "2020/07/31 12:00:00", 611, 0.0, "ダイチ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 10046, 0.0, 192401, 6.75, 2, 24, 24017, "2020/07/31 12:00:00", 612, 0.0, "ダイチ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 10046, 0.0, 192401, 0.0, 2, 24, 24018, "2020/07/31 12:00:00", 613, 0.0, "ダイチ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 10046, 0.0, 113401, 4.52, 1, 24, 24019, "2020/07/31 12:00:00", 211, 0.0, "ハツネ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 10046, 0.0, 113401, 3.89, 1, 24, 24020, "2020/07/31 12:00:00", 212, 0.0, "ハツネ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 10046, 0.0, 113401, 13.49, 2, 24, 24021, "2020/07/31 12:00:00", 213, 0.0, "ハツネ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 10046, 0.0, 106501, 3.17, 2, 24, 24022, "2020/07/31 12:00:00", 311, 0.0, "カヤ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 10046, 0.0, 106501, 4.42, 2, 24, 24023, "2020/07/31 12:00:00", 312, 0.0, "カヤ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 6, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 10046, 0.0, 106501, 2.89, 1, 24, 24024, "2020/07/31 12:00:00", 313, 0.0, "カヤ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 4, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 10046, 0.0, 102301, 3.71, 3, 24, 24025, "2020/07/31 12:00:00", 421, 0.0, "アヤネ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 10046, 0.0, 192201, 5.1, 1, 24, 24026, "2020/07/31 12:00:00", 721, 0.0, "アサヒ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 10046, 0.0, 192301, 4.34, 3, 24, 24027, "2020/07/31 12:00:00", 821, 0.0, "部員３");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "いい勝負だったよ\nまたやろうね", 10046, 0.0, 192501, 0.0, 1, 24, 24028, "2020/07/31 12:00:00", 521, 0.0, "");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 10046, 0.0, 113501, 5.62, 2, 24, 24029, "2020/07/31 12:00:00", 101, -360.0, "ミサト");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 10046, 0.0, 113501, 9.58, 2, 24, 24030, "2020/07/31 12:00:00", 102, -360.0, "ミサト");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 10046, 0.0, 113501, 0.0, 2, 24, 24031, "2020/07/31 12:00:00", 103, -360.0, "ミサト");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 2, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 10046, 0.0, 113501, 9.13, 1, 24, 24032, "2020/07/31 12:00:00", 104, -360.0, "ミサト");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2030/12/17 14:59:59", 1, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 10046, 0.0, 113501, 8.27, 2, 24, 24033, "2020/07/31 12:00:00", 105, -360.0, "ミサト");
